"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";

// Popover: generated by UIX from the design system. Same variants and sizes as the Figma component.

const popoverVariants = cva(
  "fixed inset-auto m-0 hidden w-[280px] flex-col open:flex gap-2 p-4 bg-surface text-fg-primary border border-line-default rounded-lg shadow-lg",
  {
    variants: {
      placement: {
        bottom: "origin-top",
        top: "origin-bottom",
      },
    },
    defaultVariants: {
      placement: "bottom",
    },
  },
);

export interface PopoverProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "title">,
    VariantProps<typeof popoverVariants> {
  /** The element that opens the panel (a Button): it gets the popovertarget attribute. */
  trigger: React.ReactElement;
  title?: React.ReactNode;
  /** Buttons at the end of the panel. */
  actions?: React.ReactNode;
}

const Popover = React.forwardRef<HTMLDivElement, PopoverProps>(
  ({ className, placement, trigger, title, actions, children, id, ...props }, ref) => {
    const autoId = React.useId();
    const panelId = id ?? autoId;
    const panel = React.useRef<HTMLDivElement | null>(null);
    React.useImperativeHandle(ref, () => panel.current as HTMLDivElement);
    React.useEffect(() => {
      const node = panel.current;
      if (!node) return;
      // The panel sits in the top layer; place it next to the trigger each time it opens.
      const onToggle = (event: Event) => {
        if ((event as Event & { newState?: string }).newState !== "open") return;
        const anchor = document.querySelector('[popovertarget="' + panelId + '"]');
        if (!anchor) return;
        const a = anchor.getBoundingClientRect();
        const p = node.getBoundingClientRect();
        const top = placement === "top" ? a.top - p.height - 8 : a.bottom + 8;
        node.style.top = Math.max(8, top) + "px";
        node.style.left = Math.max(8, Math.min(window.innerWidth - p.width - 8, a.left + a.width / 2 - p.width / 2)) + "px";
      };
      node.addEventListener("toggle", onToggle);
      return () => node.removeEventListener("toggle", onToggle);
    }, [panelId, placement]);
    const popoverProps: Record<string, string> = { popover: "auto" };
    const triggerProps: Record<string, string> = { popovertarget: panelId };
    return (
      <>
        {React.cloneElement(trigger as React.ReactElement<Record<string, string>>, triggerProps)}
        <div ref={panel} id={panelId} {...popoverProps} data-slot="popover" data-kind="overlay" className={cn(popoverVariants({ placement }), className)} {...props}>
          {title ? <p className="text-label-large text-fg-primary">{title}</p> : null}
          <div className="text-body-small text-fg-secondary">{children}</div>
          {actions ? <div className="flex justify-end gap-2 pt-2">{actions}</div> : null}
        </div>
      </>
    );
  },
);
Popover.displayName = "Popover";

export { Popover, popoverVariants };
